package org.traccar.protocol;

import org.junit.Test;
import static org.junit.Assert.*;
import org.traccar.Protocol;
import java.net.InetSocketAddress;
import io.netty.channel.Channel;
import static org.mockito.Mockito.*;

public class WatchProtocolDecoderTest {

    @Test
    public void getHasIndexTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("w", 1, null, null));
        assertFalse(decoder.getHasIndex());
    }

    @Test
    public void getManufacturerTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("w", 1, null, null));
        assertEquals("Unknown", decoder.getManufacturer());
    }  

    @Test
    public void decodeWithoutChannelTest() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("w", 1, null, null));
        assertNull(decoder.decode(null, new InetSocketAddress("localhost", 0), "test message"));
    }

    @Test
    public void decodeWithChannelTest() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("w", 1, null, null));

        Channel channel = mock(Channel.class);
        when(channel.remoteAddress()).thenReturn(new InetSocketAddress("localhost", 0));

        assertNotNull(decoder.decode(channel, new InetSocketAddress("localhost", 0), "test message"));
    }

    @Test
    public void decodeInvalidMessageTest() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("w", 1, null, null));

        Channel channel = mock(Channel.class);
        when(channel.remoteAddress()).thenReturn(null);

        assertNull(decoder.decode(channel, new InetSocketAddress("localhost", 0), "invalid message"));
    }
}  
